/* PixelSnow: canvas adaptation of the user's React Bits reference for this vanilla HTML site. */
(() => {
  const SPRITES = [
    ['@'],
    ['.x.', 'x@x', '.x.'],
    ['..x..', 'x.o.x', '.o@o.', 'x.o.x', '..x..'],
    ['...x...', '.x.o.x.', '..ooo..', 'xoo@oox', '..ooo..', '.x.o.x.', '...x...'],
    ['....x....', '.x..o..x.', '..o.o.o..', '...ooo...', 'xooo@ooox', '...ooo...', '..o.o.o..', '.x..o..x.', '....x....'],
    ['x...x', '.o.o.', '..@..', '.o.o.', 'x...x'],
    ['x..x..x', '.o.o.o.', '..ooo..', 'xoo@oox', '..ooo..', '.o.o.o.', 'x..x..x'],
    ['x...x...x', '.o..o..o.', '..o.o.o..', '...ooo...', 'xooo@ooox', '...ooo...', '..o.o.o..', '.o..o..o.', 'x...x...x']
  ];
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(a,b)=>a+Math.random()*(b-a);
  class PixelSnow {
    constructor(canvas, options={}) {
      this.canvas=canvas;this.canvas.classList.add('pixel-snow-canvas');this.ctx=canvas.getContext('2d',{alpha:true});this.options={density:.5,speed:1,wind:0,sway:.5,flakeSize:1,pixelSize:2,depth:.65,brightness:1,glow:.7,twinkle:.38,accumulate:true,sizeScale:1,mouseInteraction:true,paused:false,...options};
      this.flakes=[];this.surfaces=[];this.surfaceMap=new WeakMap();this.surfaceScanAt=0;this.snowmanCooldown=0;this.width=1;this.height=1;this.ratio=1;this.pointer={x:-1000,y:-1000,vx:0,vy:0,at:0};this.last=0;this.raf=0;this.running=false;this.motion=matchMedia('(prefers-reduced-motion: reduce)');
      this.resize=()=>this.measure();this.move=e=>this.onPointer(e);this.leave=()=>{this.pointer.x=-1000};
      addEventListener('resize',this.resize,{passive:true});addEventListener('pointermove',this.move,{passive:true});document.documentElement.addEventListener('pointerleave',this.leave);this.lastScroll=0;this.scrollFrame=0;addEventListener('scroll',()=>{if(this.scrollFrame)return;this.scrollFrame=requestAnimationFrame(()=>{this.scrollFrame=0;this.scanSurfaces(true);this.draw()})},{passive:true});document.addEventListener('visibilitychange',()=>this.sync());this.motion.addEventListener?.('change',()=>this.sync());
      this.measure();this.sync();
    }
    set(values){const resizeFlakes=Object.hasOwn(values,'flakeSize')&&values.flakeSize!==this.options.flakeSize;Object.assign(this.options,values);if(resizeFlakes)for(const f of this.flakes)f.level=this.pickLevel();this.rebuild();if(this.options.paused||this.motion.matches)this.draw();this.sync()}
    measure(){this.width=innerWidth;this.height=innerHeight;this.ratio=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(this.width*this.ratio);this.canvas.height=Math.round(this.height*this.ratio);this.ctx.setTransform(this.ratio,0,0,this.ratio,0,0);this.rebuild();this.scanSurfaces(true);this.draw()}
    rebuild(){const count=Math.round(clamp(this.width*this.height*this.options.density/1500,0,4000));while(this.flakes.length<count)this.flakes.push(this.spawn(false));this.flakes.length=count}
    spawn(fromTop=true){const level=this.pickLevel();return {x:rand(-20,this.width+20),y:fromTop?rand(-45,-8):rand(0,this.height),level,alt:Math.random()<.5,vx:0,vy:0,phase:rand(0,Math.PI*2),rate:rand(.6,1.5),drift:rand(.7,1.3),sparkle:rand(0,100)}}
    pickLevel(){const size=clamp(this.options.flakeSize,0,2),weights=[.46,.27,.15,.08,.04].map((w,i)=>w*Math.pow(2.2,(size-1)*(i-1.5))),sum=weights.reduce((a,b)=>a+b,0);let value=Math.random()*sum;for(let i=0;i<weights.length;i++){value-=weights[i];if(value<=0)return i}return 4}
    scanSurfaces(force=false){const now=performance.now();if(!force&&now-this.surfaceScanAt<450)return;this.surfaceScanAt=now;const nodes=document.querySelectorAll('.tree-panel,.note-form,.drawing,.weather-controls');const alive=new Set();for(const el of nodes){const r=el.getBoundingClientRect();if(r.width<100||r.height<30)continue;alive.add(el);let item=this.surfaceMap.get(el);const bins=Math.max(12,Math.ceil(r.width/5));if(!item){item={el,left:r.left+scrollX,top:r.top+scrollY,width:r.width,height:r.height,pile:new Float32Array(bins),snowman:null};this.surfaceMap.set(el,item)}else if(item.pile.length!==bins){const old=item.pile;item.pile=new Float32Array(bins);for(let i=0;i<bins;i++)item.pile[i]=old[Math.min(old.length-1,Math.round(i*(old.length-1)/(bins-1)))]||0}item.left=r.left+scrollX;item.top=r.top+scrollY;item.width=r.width;item.height=r.height}this.surfaces=this.surfaces.filter(item=>item.el.isConnected);for(const el of alive){const item=this.surfaceMap.get(el);if(!this.surfaces.includes(item))this.surfaces.push(item)}}
    settleOnBlock(f,previousY,flakeHeight,now){if(!this.options.accumulate||this.options.speed<=0)return false;const scrollLeft=scrollX,scrollTop=scrollY;for(const surface of this.surfaces){const left=surface.left-scrollLeft,topEdge=surface.top-scrollTop;if(topEdge>this.height||topEdge< -35||f.x<left||f.x>left+surface.width)continue;const column=clamp(Math.floor((f.x-left)/surface.width*surface.pile.length),0,surface.pile.length-1);const top=topEdge-surface.pile[column];if(previousY+flakeHeight/2<top&&f.y+flakeHeight/2>=top){const radius=1+Math.floor(f.level*.7),amount=Math.min(2.8,1.1+f.level*.35);for(let k=-radius;k<=radius;k++){const i=column+k;if(i>=0&&i<surface.pile.length)surface.pile[i]=Math.min(24,surface.pile[i]+amount*(1-Math.abs(k)/(radius+1)))}const mound=surface.pile[column];if(!surface.snowman&&mound>=7&&now>this.snowmanCooldown&&Math.random()<.0009){surface.snowman={column,created:now};this.snowmanCooldown=now+150000}return true}}return false}
    drawDrifts(){const ctx=this.ctx;for(const s of this.surfaces){const rect=s.el.getBoundingClientRect();if(rect.width>0&&rect.height>0){s.left=rect.left+scrollX;s.top=rect.top+scrollY;s.width=rect.width;s.height=rect.height}const left=s.left-scrollX,visibleTop=s.top-scrollY;if(visibleTop< -28||visibleTop>this.height||visibleTop+s.height<0||left+s.width<0||left>this.width)continue;const step=s.width/s.pile.length;ctx.save();ctx.beginPath();ctx.moveTo(left,visibleTop+2);for(let i=0;i<s.pile.length;i++)ctx.lineTo(left+(i+.5)*step,visibleTop-s.pile[i]);ctx.lineTo(left+s.width,visibleTop+2);ctx.lineTo(left+s.width,visibleTop+5);ctx.lineTo(left,visibleTop+5);ctx.closePath();const gradient=ctx.createLinearGradient(0,visibleTop-25,0,visibleTop+5);gradient.addColorStop(0,'rgba(240,249,255,.92)');gradient.addColorStop(.42,'rgba(218,239,252,.94)');gradient.addColorStop(1,'rgba(157,199,224,.32)');ctx.fillStyle=gradient;ctx.shadowColor='rgba(208,235,255,.68)';ctx.shadowBlur=5;ctx.fill();ctx.restore();if(s.snowman)this.drawSnowman(left+s.snowman.column*step,visibleTop-s.pile[s.snowman.column],step)}}
    collectSnowAt(x,y,allowed=this.surfaces){for(const surface of allowed){const left=surface.left-scrollX,top=surface.top-scrollY,column=clamp(Math.floor((x-left)/surface.width*surface.pile.length),0,surface.pile.length-1),surfaceY=top-surface.pile[column];if(x>=left&&x<=left+surface.width&&Math.abs(surfaceY-y)<55)this.collectSnow(surface,x,y)}this.collectSnow(null,x,y)}
    collectSnow(surface,x,y){if(surface){const left=surface.left-scrollX,top=surface.top-scrollY,step=surface.width/surface.pile.length,column=clamp(Math.floor((x-left)/step),0,surface.pile.length-1),reach=Math.ceil(26/step);for(let k=-reach;k<=reach;k++){const i=column+k;if(i>=0&&i<surface.pile.length)surface.pile[i]=Math.max(0,surface.pile[i]-.95*(1-Math.abs(k)/(reach+1)))}if(surface.snowman&&Math.abs(surface.snowman.column-column)*step<25)surface.snowman=null;y=top-surface.pile[column]}for(const f of this.flakes){if(Math.abs(f.x-x)<32&&Math.abs(f.y-y)<23)Object.assign(f,this.spawn(true))}}
    drawSnowman(x,top,step){const ctx=this.ctx,u=2,y=Math.round(top)-38;const palette={w:'#edf8ff',s:'#a4cbdc',h:'#233c57',r:'#e56375',g:'#ffc875',o:'#f99b4e',e:'#162c42',b:'#825c47'};const rows=['      hhhh      ','      hhhh      ','      rrrr      ','    hhhhhhhh    ','     wwwwww     ','    wwwwwwww    ','    wewwewww    ','    wwwwoooo    ','     wwwwww     ','    rrrrrrrr    ','  b  wwwrrw  b  ',' b  wwwwwrww  b ','  bbwwwewwwwbb  ','   wwwwwwwwww   ','   wwwwewwwww   ','   wwwwwwwwww   ','    swwwwwws    ','     ssssss     '];ctx.save();ctx.shadowBlur=0;for(let j=0;j<rows.length;j++)for(let i=0;i<rows[j].length;i++){const color=palette[rows[j][i]];if(color){ctx.fillStyle=color;ctx.fillRect(Math.round(x)+(i-8)*u,y+j*u,u,u)}}ctx.restore()}

    onPointer(e){const t=performance.now(),dt=Math.max(1,t-this.pointer.at)/1000;if(this.pointer.at){this.pointer.vx=clamp((e.clientX-this.pointer.x)/dt,-2500,2500);this.pointer.vy=clamp((e.clientY-this.pointer.y)/dt,-2500,2500)}this.pointer.x=e.clientX;this.pointer.y=e.clientY;this.pointer.at=t}
    sprite(f){let variant=f.level;if(f.level>=2&&f.alt)variant+=3;return SPRITES[variant]}
    drawFlake(f,time){const ctx=this.ctx,opt=this.options,rows=this.sprite(f),unit=opt.pixelSize*opt.sizeScale*(.72+f.level*.1),size=rows.length*unit,x=Math.round((f.x-size/2)/unit)*unit,y=Math.round((f.y-size/2)/unit)*unit;const depthLight=1-opt.depth*(1-(f.level+1)/5)*.75,spark=Math.pow(Math.max(0,Math.sin(time*.9+f.sparkle)),36)*opt.twinkle;ctx.save();ctx.globalAlpha=clamp(depthLight*(.42+spark*.58)*opt.brightness,0,1);ctx.shadowColor='rgba(193,228,255,.9)';ctx.shadowBlur=opt.glow*(f.level>0?unit*(1.6+f.level*.35):1);for(let row=0;row<rows.length;row++)for(let col=0;col<rows[row].length;col++){const mark=rows[row][col];if(mark==='.')continue;ctx.fillStyle=mark==='@'?'#fff':mark==='o'?'#cbeaff':'#8fc9f1';ctx.fillRect(x+col*unit,y+row*unit,unit,unit)}ctx.restore()}
    tick=(now)=>{this.raf=0;if(!this.running||document.hidden)return;const dt=this.last?Math.min(.05,(now-this.last)/1000):1/60;this.last=now;const o=this.options,moving=!o.paused&&!this.motion.matches; if(moving){this.scanSurfaces(false);for(const f of this.flakes){const previousY=f.y;const parallax=1-o.depth*(1-(f.level+1)/5)*.75,targetX=(o.wind*46*parallax+Math.sin(now/1000*f.rate+f.phase)*o.sway*(6+f.level*7))*f.drift,targetY=[16,24,34,48,66][f.level]*parallax*o.speed*f.drift,ease=1-Math.exp(-dt*2.2);f.vx+=(targetX-f.vx)*ease;f.vy+=(targetY-f.vy)*ease;
      const dx=f.x-this.pointer.x,dy=f.y-this.pointer.y,d=Math.hypot(dx,dy);if(o.mouseInteraction&&d<115&&d>0){const near=1-d/115,force=near*near*near*1350*dt;f.vx+=dx/d*force+this.pointer.vx*near*near*dt*3;f.vy+=dy/d*force+this.pointer.vy*near*near*dt*3}
      f.x+=f.vx*dt;f.y+=f.vy*dt;const flakeHeight=this.sprite(f).length*o.pixelSize*o.sizeScale*(.72+f.level*.1);if(this.settleOnBlock(f,previousY,flakeHeight,now)){Object.assign(f,this.spawn(true));continue}if(o.speed>=0?f.y>this.height+30:f.y< -30){Object.assign(f,this.spawn(true));if(o.speed<0)f.y=this.height+rand(8,35)}if(f.x< -35)f.x=this.width+30;if(f.x>this.width+35)f.x=-30;
    }this.pointer.vx*=Math.exp(-dt*5);this.pointer.vy*=Math.exp(-dt*5)}this.draw(now/1000);if(moving||!o.paused&&this.motion.matches)this.raf=requestAnimationFrame(this.tick)}
    draw(time=0){if(!this.ctx)return;const ctx=this.ctx;ctx.clearRect(0,0,this.width,this.height);for(const f of this.flakes)this.drawFlake(f,time);this.drawDrifts()}
    sync(){const shouldRun=!document.hidden&&!this.options.paused&&!this.motion.matches;if(shouldRun){if(!this.running){this.running=true;this.last=0;this.raf=requestAnimationFrame(this.tick)}}else{this.running=false;cancelAnimationFrame(this.raf);this.raf=0;this.last=0;this.draw()}}
  }
  window.PixelSnow=PixelSnow;
})();
